import zstandard,json,collections,glob,os,time,re
def load(p):
    try:
        with open(p,'rb') as f: raw=zstandard.ZstdDecompressor().stream_reader(f).read()
    except Exception: return []
    out=[]
    for l in raw.decode('utf-8','replace').splitlines():
        try: out.append(json.loads(l))
        except Exception: pass
    return out
root='C:/Users/Administrator/.dsh/sessions'
files=glob.glob(root+'/*/*/session.v4.jsonl.zstd')
rows=sorted([(os.path.getmtime(p),p) for p in files],reverse=True)
cut=time.time()-7*86400
recent=[x for x in rows if x[0]>=cut]

orch_sessions=[]; build_lint_direct=[]
for m,p in recent:
    evts=load(p)
    tc=collections.Counter(); proj=p.split('sessions'+os.sep)[1].split(os.sep)[0]
    orch_args=[]
    for e in evts:
        if e.get('type')=='tool/call':
            nm=e['data'].get('name'); tc[nm]+=1
            a=e['data'].get('arguments','') or ''
            if nm=='orchestrate': orch_args.append(a[:140])
            if nm in ('pwsh','bash') and re.search(r'npm run (build|lint)|vite build|vue-tsc|(^|\s)eslint |(^|\s)tsc ',a): build_lint_direct.append((proj,a[:100]))
    if 'orchestrate' in tc:
        orch_sessions.append((m,proj,tc['orchestrate'],sum(tc.values()),p.split(os.sep)[-2],orch_args))

print('ORCHESTRATE SESSIONS last 7d:',len(orch_sessions))
for m,proj,no,tot,sid,args in sorted(orch_sessions,reverse=True):
    print(f"{time.strftime('%m-%d %H:%M',time.localtime(m))} | {proj[:42]:42s} orch={no}/{tot} | {sid}")
    for a in args[:2]: print('      >',a)
print('\nbuild/lint run directly in pwsh/bash:',len(build_lint_direct))
